def bubble_sort(lst):
    arr = lst[:]
    n = len(arr)
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr

print(bubble_sort([5, 3, 8, 1]))  # output: [1, 3, 5, 8]

def binary_search(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

print(binary_search([1, 3, 5, 7, 9], 5))  # output: 2

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

print(is_prime(7))   # output: True
print(is_prime(10))  # output: False

def primes_up_to(n):
    primes = []
    for num in range(2, n + 1):
        ok = True
        for p in primes:
            if p * p > num:
                break
            if num % p == 0:
                ok = False
                break
        if ok:
            primes.append(num)
    return primes

print(primes_up_to(20))  # output: [2, 3, 5, 7, 11, 13, 17, 19]

def next_power_of_two(n):
    if n <= 1:
        return 1
    p = 1
    while p < n:
        p *= 2
    return p

print(next_power_of_two(100))  # output: 128

def all_pairs_product(lst):
    pairs = []
    for i in range(len(lst)):
        for j in range(i + 1, len(lst)):
            pairs.append((i, j, lst[i] * lst[j]))
    return pairs

print(all_pairs_product([1, 2, 3]))  # output: [(0, 1, 2), (0, 2, 3), (1, 2, 6)]

def second_largest(lst):
    if len(lst) < 2:
        return None
    first = second = float("-inf")
    for x in lst:
        if x > first:
            second = first
            first = x
        elif x > second and x != first:
            second = x
    return second if second != float("-inf") else None

print(second_largest([12, 35, 1, 10]))  # output: 12
